<?php use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Logi aplikacji'; ?>
<div class="page-head"><div><p class="eyebrow">Administracja · System</p><h1>Logi aplikacji</h1></div></div>
<section class="card section-card"><form method="get" class="search-admin"><label>Poziom<select name="level"><option value="">Wszystkie</option><?php foreach(['DEBUG','INFO','WARNING','ERROR'] as $l):?><option value="<?=$l?>" <?=$level===$l?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Szukaj<input name="q" value="<?=Html::e($query)?>" maxlength="200"></label><button class="button secondary">Filtruj</button></form>
<?php if(!$rows):?><div class="empty-state"><p>Brak pasujących wpisów.</p></div><?php else:?><div class="log-viewer"><?php foreach($rows as $row):?><pre><?=Html::e($row)?></pre><?php endforeach;?></div><?php endif;?>
<nav class="pager" aria-label="Paginacja"><?php if($page>1):?><a href="<?=Html::e(Url::to('/admin/logs?'.http_build_query(['q'=>$query,'level'=>$level,'page'=>$page-1])))?>">← Poprzednia</a><?php endif;?><span>Strona <?=$page?> z <?=$pages?></span><?php if($page<$pages):?><a href="<?=Html::e(Url::to('/admin/logs?'.http_build_query(['q'=>$query,'level'=>$level,'page'=>$page+1])))?>">Następna →</a><?php endif;?></nav></section>
